() => {
  const w = window.innerWidth, h = window.innerHeight;
  const doc = document.documentElement;
  const main = document.querySelector('main');
  const info = { winW: w, winH: h, docScrollH: doc.scrollHeight, bodyScrollH: document.body.scrollHeight };
  if (main) {
    info.mainScrollH = main.scrollHeight;
    info.mainClientH = main.clientHeight;
    info.mainOverflow = getComputedStyle(main).overflowY;
  }
  // find scrollable elements
  const scrollables = [];
  document.querySelectorAll('*').forEach(el => {
    const s = getComputedStyle(el);
    if ((s.overflowY === 'auto' || s.overflowY === 'scroll') && el.scrollHeight > el.clientHeight + 10) {
      scrollables.push({ tag: el.tagName, cls: (el.className||'').toString().slice(0,60), scrollH: el.scrollHeight, clientH: el.clientHeight });
    }
  });
  info.scrollables = scrollables.slice(0, 8);
  return info;
}

() => {
  try { window.resizeTo(1600, 1000); } catch (e) { return 'resize failed: ' + e.message; }
  return { w: window.innerWidth, h: window.innerHeight };
}

() => ({
  innerW: window.innerWidth, innerH: window.innerHeight,
  outerW: window.outerWidth, outerH: window.outerHeight,
  screenW: screen.width, screenH: screen.height,
  devicePixelRatio: window.devicePixelRatio
})

() => {
  const scroller = document.querySelector('div.flex-1.overflow-y-auto');
  if (!scroller) return 'scroller not found';
  const changed = [];
  let el = scroller;
  while (el && el !== document.documentElement) {
    const cs = getComputedStyle(el);
    const orig = el.getAttribute('style') || '';
    changed.push([el, orig]);
    el.style.setProperty('height', 'auto', 'important');
    el.style.setProperty('max-height', 'none', 'important');
    el.style.setProperty('overflow', 'visible', 'important');
    el.style.setProperty('flex', 'none', 'important');
    el = el.parentElement;
  }
  document.documentElement.style.setProperty('height', 'auto', 'important');
  document.body.style.setProperty('height', 'auto', 'important');
  document.body.style.setProperty('overflow', 'visible', 'important');
  window.__restoreStyles = () => { changed.forEach(([el, orig]) => { el.setAttribute('style', orig); }); document.documentElement.removeAttribute('style'); return 'restored'; };
  scroller.scrollTop = 0;
  window.scrollTo(0, 0);
  return { docScrollH: document.documentElement.scrollHeight, bodyScrollH: document.body.scrollHeight };
}

() => {
  const scroller = document.querySelector('div.flex-1.overflow-y-auto');
  if (scroller) scroller.scrollTop = scroller.scrollHeight;
  // find status table horizontal scroll container
  const els = [...document.querySelectorAll('div')];
  const hscrolls = els.filter(el => el.scrollWidth > el.clientWidth + 5 && /overflow-x|overflow-auto|overflow-scroll/.test(getComputedStyle(el).overflowX + getComputedStyle(el).overflow));
  const info = hscrolls.map(el => ({ cls: (el.className||'').toString().slice(0,50), sw: el.scrollWidth, cw: el.clientWidth }));
  // scroll them to reveal right side
  hscrolls.forEach(el => { el.scrollLeft = el.scrollWidth; });
  return { scrolledToBottom: !!scroller, hscrolls: info.slice(0,5) };
}

() => {
  const scroller = document.querySelector('div.flex-1.overflow-y-auto');
  if (!scroller) return 'not found';
  scroller.scrollTop = scroller.scrollHeight;
  return { scrollTop: scroller.scrollTop, scrollHeight: scroller.scrollHeight, overflowY: getComputedStyle(scroller).overflowY };
}

() => {
  const all = [...document.querySelectorAll('div.flex-1.overflow-y-auto')];
  return {
    count: all.length,
    items: all.map(el => ({ cls: el.className.slice(0, 80), sh: el.scrollHeight, ch: el.clientHeight })),
    docH: document.documentElement.scrollHeight,
    winH: window.innerHeight
  };
}

() => {
  const scroller = document.querySelector('div.flex-1.overflow-y-auto.bg-slate-950');
  scroller.scrollTop = scroller.scrollHeight;
  return { scrollTop: scroller.scrollTop, scrollHeight: scroller.scrollHeight };
}

() => {
  // find the status distribution table
  const tables = [...document.querySelectorAll('table')];
  const t = tables.find(tb => tb.textContent.includes('缓存命中'));
  if (!t) return 'table not found';
  const rows = [...t.querySelectorAll('tr')].slice(1).map(tr => {
    const cells = [...tr.querySelectorAll('td,th')].map(td => td.textContent.trim().slice(0, 24));
    // detect bar: look for inner div with width style or gradient
    const bars = [...tr.querySelectorAll('div')].filter(d => d.style && d.style.width).map(d => d.style.width);
    return { cells, bars };
  });
  const wrap = t.closest('div');
  const wrapStyle = wrap ? getComputedStyle(wrap) : null;
  return {
    rows,
    tableW: t.scrollWidth,
    wrapW: wrap ? wrap.clientWidth : null,
    wrapOverflowX: wrapStyle ? wrapStyle.overflowX : null
  };
}

() => {
  const tables = [...document.querySelectorAll('table')];
  const t = tables.find(tb => tb.textContent.includes('缓存命中'));
  const wrap = t.closest('div');
  wrap.scrollLeft = wrap.scrollWidth;
  // also make sure the status section is in view vertically
  const scroller = document.querySelector('div.flex-1.overflow-y-auto.bg-slate-950');
  const secTitle = [...document.querySelectorAll('*')].find(el => el.children.length === 0 && /问数状态分布/.test(el.textContent));
  if (secTitle) secTitle.scrollIntoView({ block: 'start' });
  return { wrapScrollLeft: wrap.scrollLeft, wrapScrollWidth: wrap.scrollWidth };
}
